    fun forLanguage(language: AppLanguage): Map<String, String> {
        return when (language) {
            AppLanguage.PT -> PT
            AppLanguage.ES -> ES
            AppLanguage.FR -> FR
            AppLanguage.ID -> ID
            AppLanguage.ZH -> ZH
            AppLanguage.RU -> RU
            AppLanguage.UK -> UK
            else -> EN
        }
    }
}

object LocalizationManager {
    val language = MutableStateFlow(DesktopSettingsStore.loadLanguage())

    fun setLanguage(language: AppLanguage) {
        if (this.language.value == language) return
        this.language.value = language
        DesktopSettingsStore.saveLanguage(language)
    }

    fun currentStrings(): Strings {
        return Strings(Translations.forLanguage(language.value))
    }
}

internal object ThemeManager {
    val themeMode = MutableStateFlow(DesktopSettingsStore.loadThemeMode())

    fun setThemeMode(themeMode: ThemeMode) {
        if (this.themeMode.value == themeMode) return
        this.themeMode.value = themeMode
        DesktopSettingsStore.saveThemeMode(themeMode)
    }
}
